#!/bin/bash
echo "=== 玄机算命 一键部署 ==="
echo "解压中..."
python3 -c "
import sys, base64, gzip, tarfile, io
data = base64.b64decode(''''''')
gz_data = gzip.decompress(data)
import tarfile, io
tar = tarfile.open(fileobj=io.BytesIO(gz_data))
tar.extractall('/root')
print('解压完成')
"
echo "设置权限..."
chmod +x /root/deploy.sh
echo "安装依赖..."
pip3 install -r /root/requirements.txt
echo "启动服务..."
pkill -f gunicorn 2>/dev/null
cd /root && nohup python3 -m gunicorn -c gunicorn_config.py api.app:app > /tmp/gunicorn.log 2>&1 &
sleep 2
ps aux | grep gunicorn | grep -v grep && echo "✅ 部署成功！" || echo "❌ 启动失败"
echo "访问: http://$(curl -s ifconfig.me):8000"
